// Rebuild every Lexicon Realms zone module (dev tool; deterministic; never at runtime).
//
//   node tools/maps/build_world.mjs            writes src/data/maps/{willowmere,valley,downs,moor}.js,
//                                              assets/tiles/tiles.json (trimmed to the ids the zones use) and copies
//                                              the tile sheets they need from Lexicon Quest (READ ONLY source)
//
// Every zone is generated by zone_*.mjs in this folder. Willowmere was Lexicon Quest's map as is until the 2026-11-21
// relayout (approved by Scott); it is now Realms' own drawing (zone_willowmere.mjs) and LQ is not its source. The
// valley, the Downs and the High Moor use LQ's own tiles, autotiles and props, laid out by hand-placed polylines and
// landmarks with a little value noise for texture; the town is drawn street by street. After baking collision every spawn, NPC, node, lantern and hook is snapped onto a walkable cell
// and checked reachable on foot from the zone's arrival; a failure stops the build (BUILD_WORLD_FAIL).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { LQ, loadLqDb, bakeCollision, usedIds, reach, nearestWalk, writeModule, canStep, respreadZone } from './kit.mjs';
import { PROGRESSION } from '../../src/data/progression.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
// --out <dir> writes the zone modules elsewhere (diffing a change); --no-assets skips assets/tiles (the map lane only
// changes sim data: the tile sheets and tiles.json only change when the tiles a zone uses change)
const argOut = process.argv.indexOf('--out');
const OUT = argOut >= 0 ? path.resolve(process.argv[argOut + 1]) : path.join(ROOT, 'src', 'data', 'maps');
const NO_ASSETS = process.argv.includes('--no-assets');
const db = loadLqDb();
const problems = [];
const warn = (s) => console.warn('  warn: ' + s);

// ---------------------------------------------------------------- Willowmere (Realms' own drawing, zone_willowmere.mjs)
// The town's zone file returns { map, realm } like the others; the module keeps Willowmere's field order (the lq block,
// the levels before the areas) and is not respread (it is a level 1 town).
async function willowmere() {
  const { map, realm } = (await import('./zone_willowmere.mjs')).build(db);
  const collision = bakeCollision(map, db);
  const { joins, lq, levels, areas, lanterns, npcs, spawns, nodes, signs, hooks, arrival } = realm;
  return {
    id: map.id, name: map.name, kind: map.kind, source: 'tools/maps/zone_willowmere.mjs', w: map.w, h: map.h,
    music: map.music, lighting: map.lighting, under: map.under, legend: map.legend, ground: map.ground,
    overlays: map.overlays, decor: map.decor, overhead: map.overhead, collision,
    joins, lq, levels, areas, lanterns, npcs, spawns, nodes, signs, hooks, arrival,
  };
}

// ---------------------------------------------------------------- generated zones
function generated(mod) {
  const { map, realm } = mod.build(db);
  const collision = bakeCollision(map, db);
  const z = { ...map, source: `tools/maps/zone_${map.id}.mjs`, collision, ...realm };
  delete z.solids; delete z.open;
  // cap 20: the zone files author levels 1 to 15; ship them re-spread over 1 to 20 (PROGRESSION.zoneRespread)
  return respreadZone(z, PROGRESSION.zoneRespread);
}

function finish(z) {
  const isWalk = (x, y) => z.collision[y] && z.collision[y][x] === '.';
  const snap = (p, what) => {
    if (isWalk(p.x, p.y)) return;
    const n = nearestWalk(z, p.x, p.y, 4);
    if (!n) { problems.push(`${z.id}: ${what} at ${p.x},${p.y} has no walkable cell near`); return; }
    warn(`${z.id}: ${what} moved ${p.x},${p.y} -> ${n[0]},${n[1]}`);
    p.x = n[0]; p.y = n[1];
  };
  for (const s of z.spawns || []) snap(s, `spawn ${s.mob}`);
  for (const s of z.npcs || []) snap(s, `npc ${s.npc}`);
  for (const s of z.nodes || []) snap(s, `node ${s.id}`);
  for (const s of z.lanterns || []) snap(s, `lantern ${s.id}`);
  for (const s of z.hooks || []) snap(s, `hook ${s.id}`);
  const [ax, ay] = z.arrival;
  if (!isWalk(ax, ay)) problems.push(`${z.id}: arrival ${ax},${ay} not walkable`);
  const seen = reach(z, ax, ay);
  const ok = (x, y) => seen[y * z.w + x] === 1;
  for (const [k, list] of [['spawn', z.spawns], ['npc', z.npcs], ['node', z.nodes], ['lantern', z.lanterns], ['hook', z.hooks]]) {
    for (const p of list || []) if (!ok(p.x, p.y)) problems.push(`${z.id}: ${k} ${p.mob || p.npc || p.id} at ${p.x},${p.y} is not reachable from the arrival`);
  }
  for (const a of z.areas || []) {
    let any = false;
    for (let y = a.y; y < a.y + a.h && !any; y++) for (let x = a.x; x < a.x + a.w; x++) if (x < z.w && y < z.h && ok(x, y)) { any = true; break; }
    if (!any) problems.push(`${z.id}: area ${a.id} has no reachable cell`);
  }
  // pits: a reachable cell from which neither the arrival nor any join can be reached again (one-way ledges into a
  // pocket) is a softlock (PLAYTEST_BOT bug 2). Walk the step graph backwards from the arrival and every join cell.
  const back = new Uint8Array(z.w * z.h);
  const bq = [];
  const seed = (x, y) => { if (x >= 0 && y >= 0 && x < z.w && y < z.h && !back[y * z.w + x]) { back[y * z.w + x] = 1; bq.push([x, y]); } };
  seed(ax, ay);
  for (const j of z.joins || []) for (let y = j.y; y < j.y + j.h; y++) for (let x = j.x; x < j.x + j.w; x++) if (ok(x, y)) seed(x, y);
  while (bq.length) {
    const [x, y] = bq.pop();
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const px = x - dx, py = y - dy;
      if (px < 0 || py < 0 || px >= z.w || py >= z.h || back[py * z.w + px]) continue;
      if (!ok(px, py)) continue;
      if (canStep(z, px, py, dx, dy)) { back[py * z.w + px] = 1; bq.push([px, py]); }
    }
  }
  // secrets (landscape pass, kit.mjs carveSecret): the passage is walkable, the chest reachable, and the nook sealed:
  // from the chest, walking without the passage cells, every cell reached lies in the nook box (no back door out of
  // the zone, round a quest gate or onto a cliff top)
  for (const s of z.secrets || []) {
    for (const [x, y] of s.passage) if (!isWalk(x, y)) problems.push(`${z.id}: secret ${s.id} passage ${x},${y} is not walkable`);
    if (!ok(s.chest.x, s.chest.y)) problems.push(`${z.id}: secret ${s.id} chest ${s.chest.x},${s.chest.y} is not reachable`);
    const pass = new Set(s.passage.map(([x, y]) => `${x},${y}`));
    const inNook = (x, y) => x >= s.nook.x && y >= s.nook.y && x < s.nook.x + s.nook.w && y < s.nook.y + s.nook.h;
    const sq = [[s.chest.x, s.chest.y]], sseen = new Set([`${s.chest.x},${s.chest.y}`]);
    while (sq.length) {
      const [x, y] = sq.pop();
      if (!inNook(x, y)) { problems.push(`${z.id}: secret ${s.id} leaks at ${x},${y}`); break; }
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const k = `${x + dx},${y + dy}`;
        if (sseen.has(k) || pass.has(k) || !isWalk(x + dx, y + dy)) continue;
        sseen.add(k); sq.push([x + dx, y + dy]);
      }
    }
    s.chest.levels = [...(z.levels || [1, 1])];
  }
  const pits = [];
  for (let y = 0; y < z.h; y++) for (let x = 0; x < z.w; x++) if (ok(x, y) && !back[y * z.w + x]) pits.push(`${x},${y}`);
  if (pits.length) problems.push(`${z.id}: ${pits.length} reachable cells with no way back (pits): ${pits.slice(0, 12).join(' ')}`);
  let walk = 0, reached = 0;
  for (let y = 0; y < z.h; y++) for (let x = 0; x < z.w; x++) if (isWalk(x, y)) { walk++; if (ok(x, y)) reached++; }
  console.log(`${z.id}: ${z.w}x${z.h}  walkable ${walk}, reachable ${reached} (${(100 * reached / walk).toFixed(1)}%)  spawns ${(z.spawns || []).length} npcs ${(z.npcs || []).length} nodes ${(z.nodes || []).length}`);
  return z;
}

const gens = [];
for (const id of ['valley', 'downs', 'moor']) {
  if (!fs.existsSync(path.join(path.dirname(fileURLToPath(import.meta.url)), `zone_${id}.mjs`))) { console.warn(`  (no zone_${id}.mjs yet)`); continue; }
  gens.push(generated(await import(`./zone_${id}.mjs`)));
}
const zones = [await willowmere(), ...gens].map(finish);

// joins land on walkable, reachable cells on the other side
const byId = Object.fromEntries(zones.map((z) => [z.id, z]));
for (const z of zones) for (const j of z.joins) {
  const o = byId[j.to];
  if (!o) continue;
  if (!(o.collision[j.ty] && o.collision[j.ty][j.tx] === '.')) problems.push(`${z.id} join -> ${j.to} ${j.tx},${j.ty} lands on '${o.collision[j.ty] && o.collision[j.ty][j.tx]}'`);
  if (!o.joins.some((k) => k.to === z.id)) problems.push(`${z.id} join -> ${j.to}: no join back`);
}

if (problems.length) {
  console.log('BUILD_WORLD_FAIL\n  ' + problems.join('\n  '));
  process.exitCode = 1;
}

// ---------------------------------------------------------------- write
const ids = new Set();
for (const z of zones) {
  usedIds(z, ids);
  const header = `// GENERATED by tools/maps/build_world.mjs from tools/maps/zone_${z.id}.mjs. Do not hand-edit: change the generator and re-run.\n// Zone shape: docs/CONTRACTS.md section 6.`;
  writeModule(path.join(OUT, `${z.id}.js`), header, z);
}
const T = db.tiles;
const pick = (obj) => Object.fromEntries(Object.entries(obj).filter(([k]) => ids.has(k) || ids.has(`${k}_top`) || ids.has(`${k}_face`)));
const trimmed = {
  version: T.version, tileSize: T.tileSize,
  source: 'LexiconQuest next/assets/tiles/tiles.json + x1_tiles.json (merged as LQ packs.js does), trimmed by tools/maps/build_world.mjs',
  collisionCodes: T.collisionCodes, terrainOrder: T.terrainOrder,
  terrains: pick(T.terrains), walls: pick(T.walls), tiles: pick(T.tiles), objects: pick(T.objects),
};
const sheets = new Set();
for (const k of ['terrains', 'walls', 'tiles', 'objects']) for (const v of Object.values(trimmed[k])) sheets.add(v.sheet);
const tilesOut = path.join(ROOT, 'assets', 'tiles');
if (NO_ASSETS) {
  const cur = fs.existsSync(path.join(tilesOut, 'tiles.json')) ? fs.readFileSync(path.join(tilesOut, 'tiles.json'), 'utf8') : '';
  if (cur !== JSON.stringify(trimmed)) { console.log('  NOTE: assets/tiles/tiles.json would change (tile ids used changed); re-run without --no-assets'); }
} else {
  fs.writeFileSync(path.join(tilesOut, 'tiles.json'), JSON.stringify(trimmed));
  for (const s of sheets) fs.copyFileSync(path.join(LQ, 'assets', 'tiles', s), path.join(tilesOut, s));
  for (const f of ['props.json', 'props.png']) fs.copyFileSync(path.join(LQ, 'assets', 'sprites', f), path.join(tilesOut, f));
}
console.log(`tiles.json: ${Object.keys(trimmed.terrains).length} terrains, ${Object.keys(trimmed.walls).length} walls, ${Object.keys(trimmed.tiles).length} tiles, ${Object.keys(trimmed.objects).length} objects; sheets ${[...sheets].join(', ')}`);
console.log(problems.length ? `BUILD_WORLD: ${problems.length} problems` : 'BUILD_WORLD_OK');
